CREATE TABLE users ({PK}, uuid VARCHAR(36) NOT NULL UNIQUE, username VARCHAR(64) NOT NULL UNIQUE, email VARCHAR(191) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, disabled INTEGER NOT NULL DEFAULT 0, totp_secret TEXT NULL, totp_enabled INTEGER NOT NULL DEFAULT 0, totp_last_step INTEGER NOT NULL DEFAULT 0, recovery_codes TEXT NULL, password_changed_at INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE user_sessions ({PK}, user_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, ip VARCHAR(45) NOT NULL, ua VARCHAR(255) NOT NULL, created_at INTEGER NOT NULL, last_seen INTEGER NOT NULL);
CREATE TABLE rate_limits (k VARCHAR(191) NOT NULL PRIMARY KEY, hits INTEGER NOT NULL, reset_at INTEGER NOT NULL);
CREATE TABLE api_keys ({PK}, user_id INTEGER NOT NULL, identifier VARCHAR(16) NOT NULL UNIQUE, token_hash VARCHAR(64) NOT NULL, memo VARCHAR(191) NOT NULL, allowed_ips TEXT NULL, last_used INTEGER NULL, created_at INTEGER NOT NULL);
CREATE TABLE locations ({PK}, short VARCHAR(60) NOT NULL UNIQUE, description VARCHAR(191) NOT NULL DEFAULT '');
CREATE TABLE nodes ({PK}, uuid VARCHAR(36) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, location_id INTEGER NOT NULL, fqdn VARCHAR(191) NOT NULL, scheme VARCHAR(5) NOT NULL DEFAULT 'https', daemon_port INTEGER NOT NULL DEFAULT 8443, daemon_secret TEXT NOT NULL, memory INTEGER NOT NULL, disk INTEGER NOT NULL, description VARCHAR(255) NOT NULL DEFAULT '', maintenance INTEGER NOT NULL DEFAULT 0, max_servers INTEGER NOT NULL DEFAULT 0, mem_over INTEGER NOT NULL DEFAULT 0, disk_over INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE allocations ({PK}, node_id INTEGER NOT NULL, ip VARCHAR(45) NOT NULL, port INTEGER NOT NULL, server_id INTEGER NULL, UNIQUE (node_id, ip, port));
CREATE TABLE eggs ({PK}, name VARCHAR(100) NOT NULL, category VARCHAR(40) NOT NULL DEFAULT 'custom', preset_key VARCHAR(40) NULL,description VARCHAR(255) NOT NULL DEFAULT '', docker_image VARCHAR(191) NOT NULL, startup TEXT NOT NULL, stop_command VARCHAR(100) NOT NULL DEFAULT '', variables TEXT NOT NULL, install_image VARCHAR(191) NOT NULL DEFAULT '', install_script TEXT NOT NULL);
CREATE TABLE servers ({PK}, uuid VARCHAR(36) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL DEFAULT '', owner_id INTEGER NOT NULL, node_id INTEGER NOT NULL, egg_id INTEGER NOT NULL, allocation_id INTEGER NOT NULL, memory INTEGER NOT NULL, cpu INTEGER NOT NULL, disk INTEGER NOT NULL, env TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', oom_kill INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE audit_log ({PK}, user_id INTEGER NULL, action VARCHAR(100) NOT NULL, target VARCHAR(191) NOT NULL DEFAULT '', ip VARCHAR(45) NOT NULL, meta TEXT NULL, created_at INTEGER NOT NULL);
CREATE INDEX idx_sessions_user ON user_sessions (user_id);
CREATE INDEX idx_servers_owner ON servers (owner_id);
CREATE INDEX idx_audit_time ON audit_log (created_at);
CREATE TABLE settings (k VARCHAR(191) NOT NULL PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE password_resets ({PK}, user_id INTEGER NOT NULL, token_hash VARCHAR(64) NOT NULL UNIQUE, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE db_hosts ({PK}, name VARCHAR(100) NOT NULL, host VARCHAR(191) NOT NULL, port INTEGER NOT NULL DEFAULT 3306, admin_user VARCHAR(100) NOT NULL, admin_pass TEXT NOT NULL, max_dbs INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE server_dbs ({PK}, server_id INTEGER NOT NULL, host_id INTEGER NOT NULL, db_name VARCHAR(64) NOT NULL UNIQUE, db_user VARCHAR(32) NOT NULL UNIQUE, db_pass TEXT NOT NULL, remote VARCHAR(64) NOT NULL DEFAULT '%', created_at INTEGER NOT NULL);
